-- Phase 5B (applications): an individual's application to a listing, with snapshots of the
-- applicant and the listing taken at submission. A new table only.

-- Never wait long for a lock or run away on a busy database (squawk rules).
SET lock_timeout = '5s';
SET statement_timeout = '60s';
-- CreateEnum
CREATE TYPE "app"."application_status" AS ENUM ('SUBMITTED', 'REVIEWED', 'SHORTLISTED', 'CONTACT', 'ACCEPTED', 'REJECTED', 'WITHDRAWN');

-- CreateTable
CREATE TABLE "app"."applications" (
    "id" UUID NOT NULL,
    "number" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "opportunity_id" UUID NOT NULL,
    "applicant_user_id" UUID NOT NULL,
    "status" "app"."application_status" NOT NULL DEFAULT 'SUBMITTED',
    "message" TEXT,
    "applicant" JSONB NOT NULL,
    "listing" JSONB NOT NULL,
    "experience" JSONB NOT NULL DEFAULT '[]',
    "projects" JSONB NOT NULL DEFAULT '[]',
    "submitted_at" TIMESTAMPTZ(6) NOT NULL,
    "status_changed_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,

    CONSTRAINT "applications_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ix_applications__applicant_updated_at" ON "app"."applications"("applicant_user_id", "updated_at" DESC);

-- CreateIndex
CREATE INDEX "ix_applications__opportunity_updated_at" ON "app"."applications"("opportunity_id", "updated_at" DESC);

-- CreateIndex
CREATE INDEX "ix_applications__created_at" ON "app"."applications"("created_at" DESC);

-- CreateIndex
CREATE UNIQUE INDEX "uq_applications__number" ON "app"."applications"("number");

-- AddForeignKey
ALTER TABLE "app"."applications" ADD CONSTRAINT "fk_applications__opportunity_id" FOREIGN KEY ("opportunity_id") REFERENCES "app"."opportunities"("id") ON DELETE CASCADE ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."applications" ADD CONSTRAINT "fk_applications__applicant_user_id" FOREIGN KEY ("applicant_user_id") REFERENCES "app"."users"("id") ON DELETE CASCADE ON UPDATE RESTRICT;


-- One application per member and listing that is not WITHDRAWN (docs/app/README.md §4
-- "Applying again"): an active, ACCEPTED or REJECTED one blocks a new one.
CREATE UNIQUE INDEX "uq_applications__active" ON "app"."applications"("opportunity_id", "applicant_user_id")
  WHERE status <> 'WITHDRAWN';

-- Checks the application relies on.
ALTER TABLE "app"."applications"
  ADD CONSTRAINT ck_applications__message_length CHECK (message IS NULL OR char_length(message) <= 500),
  ADD CONSTRAINT ck_applications__snapshots_objects
    CHECK (jsonb_typeof(applicant) = 'object' AND jsonb_typeof(listing) = 'object'),
  ADD CONSTRAINT ck_applications__picks_arrays
    CHECK (jsonb_typeof(experience) = 'array' AND jsonb_typeof(projects) = 'array'),
  ADD CONSTRAINT ck_applications__experience_picked CHECK (jsonb_array_length(experience) >= 1);

SELECT app.enable_rls('app.applications');
